from pathlib import Path
import json,html
P=Path(__file__).parent
corpus=json.loads((P/'corpus.json').read_text(encoding='utf-8'))
css='''
@font-face{font-family:CurrentGeist;src:url(fonts/GeistVF.woff);font-weight:100 900;font-display:swap}
@font-face{font-family:CurrentAdjustedArial;src:local(Arial);ascent-override:85.83%;descent-override:20.52%;line-gap-override:9.33%;size-adjust:107.19%}
'''
for name,weight in [('Regular',400),('Medium',500),('SemiBold',600),('Bold',700)]:
    css+=f'@font-face{{font-family:BeVietnamPro;src:url(fonts/BeVietnamPro-{name}.ttf);font-weight:{weight};font-display:swap}}\n'
css+='@font-face{font-family:BeVietnamPro;src:url(fonts/BeVietnamPro-Italic.ttf);font-weight:400;font-style:italic;font-display:swap}\n'
for family,file in [('NotoSans','NotoSans'),('NotoSerif','NotoSerif')]:
    for style,suffix in [('normal',''),('italic','-Italic')]:
        css+=f'@font-face{{font-family:{family};src:url(fonts/{file}{suffix}-VF.ttf);font-weight:100 900;font-style:{style};font-display:swap}}\n'
css+='''
*{box-sizing:border-box}body{margin:0;background:#f7f7fa;color:#251c39;font:15px/1.6 Arial,sans-serif}header{padding:22px 28px;background:#251c39;color:#fff}h1{font-size:24px;margin:0}header p{margin:6px 0;max-width:1100px;color:#e4ddf1}.toolbar{display:flex;gap:12px;flex-wrap:wrap;padding:16px 24px;background:#fff;border-bottom:1px solid #ded8e8}button,select,input{font:inherit}button,select{padding:8px 12px;border:1px solid #9075f4;border-radius:9px;background:#fff;color:#251c39}button:focus-visible,select:focus-visible,input:focus-visible{outline:3px solid #4d3087;outline-offset:3px}.status{padding:10px 24px;font:12px/1.5 monospace;white-space:pre-wrap}.panels{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:18px;padding:18px 24px;max-width:1900px;margin:auto}.pane{padding:20px;border:1px solid #ddd4e8;border-radius:16px;background:#fff;min-width:0}.label{font:700 16px/1.5 Arial,sans-serif;color:#4d3087;margin:0 0 4px}.family{font:12px/1.5 Arial,sans-serif;color:#655b71;margin:0 0 18px}.sample{font-family:var(--ui);font-size:calc(16px * var(--scale,1));line-height:1.65}.sample p{margin:14px 0}.brand{font-family:var(--display);font-size:calc(36px * var(--scale,1));line-height:1.35;letter-spacing:.015em;margin:12px 0}.tagline{font-family:var(--display);font-style:italic;font-weight:400;font-size:calc(23px * var(--scale,1));line-height:1.6}.editorial{font-family:var(--head);font-size:calc(26px * var(--scale,1));line-height:1.5;font-weight:700;margin:16px 0}.long-title{font-family:var(--head);font-size:calc(23px * var(--scale,1));font-weight:700;line-height:1.55}.alphabet{font-size:calc(19px * var(--scale,1));line-height:1.8;overflow-wrap:anywhere}.demo-card{padding:16px;background:#f4f0fa;border:1px solid #ddd4e8;border-radius:12px}.demo-card h3{font:700 calc(19px * var(--scale,1))/1.55 var(--head);margin:0}.meta{font-size:calc(12px * var(--scale,1));line-height:1.8;color:#625a6d}.badge{display:inline-block;font-size:calc(12px * var(--scale,1));font-weight:600;background:#e8ddf5;padding:2px 8px;border-radius:6px}.sample select,.sample input{display:block;width:100%;min-width:0;font-family:var(--ui);font-size:calc(14px * var(--scale,1));line-height:1.6;margin:10px 0;padding:10px;border:1px solid #bdb3cc;border-radius:8px}.sample button{font-family:var(--ui);font-size:calc(14px * var(--scale,1));font-weight:600;background:#4d3087;color:white}.tones{font-family:var(--ui);font-size:20px;line-height:1.55}.tone-row{padding:7px 0;border-bottom:1px solid #eee}.tone-row span{display:block;letter-spacing:.07em;white-space:normal}.tone-row small{font:10px Arial,sans-serif;color:#776b85}.tone-head{font:700 13px/1.5 Arial,sans-serif}.weights p{font-size:calc(18px * var(--scale,1));line-height:1.6}.section-title{font:700 18px/1.5 Arial,sans-serif}.readout{white-space:pre-wrap;font:11px/1.55 monospace;overflow-wrap:anywhere;background:#f0edf4;padding:14px;margin:20px 24px}.footer{padding:20px 24px}.corpus-view .overview{display:none}.overview-view .corpus{display:none}.serif-view .overview{display:none}.serif-view .tones,.serif-view .alphabet{font-family:var(--head)}@media(max-width:900px){.panels{grid-template-columns:1fr}.pane{padding:18px}.toolbar{padding:12px}.panels{padding:12px}.brand{font-size:32px}} 
'''
(P/'styles.css').write_text(css,encoding='utf-8')
options=[('A — Hiện tại', 'Geist + adjusted Arial → Segoe UI; serif: Segoe UI trước Georgia', 'CurrentGeist,CurrentAdjustedArial,"Segoe UI",Roboto,Arial,sans-serif','"Segoe UI",Georgia,serif','"Palatino Linotype","Times New Roman",serif'),('B — Be Vietnam Pro + Noto Serif','UI/body Be Vietnam Pro · Editorial Noto Serif','BeVietnamPro,Arial,sans-serif','NotoSerif,Georgia,serif','NotoSerif,Georgia,serif'),('C — Noto Sans + Noto Serif','UI/body Noto Sans · Editorial Noto Serif','NotoSans,Arial,sans-serif','NotoSerif,Georgia,serif','NotoSerif,Georgia,serif')]
panes=[]
samples=['HUẾ TRAVEL PRO','Huế có chi hay?','Lịch sử Huế','Khám phá những điểm đến nổi bật.','Di chuyển ở Huế.','Những homestay xinh xắn, khách sạn tiện nghi và không gian lưu trú đầy cảm hứng cho hành trình của bạn.']
for i,(title,subtitle,ui,head,display) in enumerate(options):
    tones=''.join('<div class="tone-row"><small>NFC</small><span>'+html.escape(' · '.join(row))+'</span><small>NFD</small><span>'+html.escape(' · '.join(corpus['tone_rows_nfd'][j]))+'</span></div>' for j,row in enumerate(corpus['tone_rows_nfc']))
    pane=f'''<article class="pane" id="pane-{i}" style='--ui:{ui};--head:{head};--display:{display}'><h2 class="label">{title}</h2><p class="family">{subtitle}</p><div class="sample"><div class="overview"><div class="brand norm">{samples[0]}</div><p class="tagline norm">{samples[1]}</p><h2 class="editorial norm">{samples[2]}</h2><h3 class="editorial norm">{samples[3]}</h3><h3 class="editorial norm">{samples[4]}</h3><p class="long-title norm">{samples[5]}</p><p class="alphabet norm">{corpus['alphabet_upper']}<br>{corpus['alphabet_lower']}</p><label class="norm">Bộ lọc khoảng giá.</label><select aria-label="Khoảng giá thử nghiệm {i}"><option>Phân khúc cao cấp &amp; resort (Cần kiểm chứng)</option><option>Giá theo mùa &amp; loại phòng</option></select><input placeholder="Tìm homestay, khách sạn tiện nghi ở Huế…" aria-label="Placeholder thử nghiệm {i}"><div class="demo-card"><span class="badge norm">LƯU TRÚ · Chưa xác minh riêng</span><h3 class="norm">Khám phá không gian lưu trú đầy cảm hứng</h3><p class="norm">Những buổi chiều bên sông Hương, ánh nắng dịu và nhịp sống thong thả tạo nên một hành trình đáng nhớ. Hãy kiểm tra thông tin nguồn, điều kiện nhận phòng và liên hệ trực tiếp cơ sở trước khi lên kế hoạch.</p><p class="meta norm">Nguồn: Mẫu chữ thử nghiệm — không phải dữ liệu mới của website.</p><button type="button">Khám phá Huế ngay</button></div><div class="weights">{''.join(f'<p class="norm" style="font-weight:{w}">{w} — Ă Â Đ Ê Ô Ơ Ư · Tiếng Việt đủ dấu.</p>' for w in [400,500,600,700])}<p class="tagline norm">Huế có chi hay? — Italic 400</p></div></div><div class="corpus"><p class="tone-head">29 chữ cái × hoa/thường · 12 nguyên âm × 6 thanh × 2 kiểu chữ</p><p class="alphabet">{corpus['alphabet_upper']}<br>{corpus['alphabet_lower']}</p><p class="tone-head">Thứ tự: ngang · sắc · huyền · hỏi · ngã · nặng</p><div class="tones">{tones}</div></div></div></article>'''
    panes.append(pane)
doc='''<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>HUẾ — Typography Preview 07-03A</title><link rel="stylesheet" href="styles.css"><body class="overview-view"><header><h1>GATE 07-03A · Preview typography độc lập</h1><p>CHƯA ĐƯỢC OWNER CHỌN FONT. Không kết nối hoặc sửa font production. “HUẾ TRAVEL PRO” dưới đây chỉ là mẫu chữ thử, không thay logo/wordmark đã LOCK.</p></header><nav class="toolbar" aria-label="Điều khiển preview"><button data-view="overview">Mẫu giao diện</button><button data-view="corpus">Toàn bộ NFC / NFD — UI</button><button data-view="serif">Toàn bộ NFC / NFD — heading</button><label>Chuẩn hóa mẫu <select id="normalization"><option>NFC</option><option>NFD</option></select></label><label>Cỡ chữ thử <select id="size"><option value="1">100%</option><option value="1.25">125%</option><option value="1.5">150%</option></select></label><span>Cỡ chữ thử ≠ browser zoom.</span></nav><div id="status" class="status">Đang tải font…</div><main class="panels">'''+''.join(panes)+'''</main><details class="readout"><summary>Trạng thái font, mẫu glyph và số đo (preview)</summary><pre id="metrics"></pre></details><footer class="footer">Self-host trong thư mục thử nghiệm · Không cài font hệ điều hành · <a href="bevietnampro-OFL.txt">OFL Be Vietnam Pro</a> · <a href="notosans-OFL.txt">OFL Noto Sans</a> · <a href="notoserif-OFL.txt">OFL Noto Serif</a></footer><script src="preview.js"></script></body></html>'''
(P/'index.html').write_text(doc,encoding='utf-8')
js='''
const params=new URLSearchParams(location.search);let view=params.get('view')||'overview';document.body.className=view+'-view';
document.querySelectorAll('[data-view]').forEach(b=>b.onclick=()=>{view=b.dataset.view;document.body.className=view+'-view';history.replaceState(null,'','?view='+view);});
document.querySelectorAll('.norm').forEach(e=>e.dataset.original=e.innerHTML);
document.querySelector('#normalization').onchange=e=>{document.querySelectorAll('.norm').forEach(n=>n.innerHTML=n.dataset.original.normalize(e.target.value));};
document.querySelector('#size').onchange=e=>{document.documentElement.style.setProperty('--scale',e.target.value);};
async function validate(){
  const families=['CurrentGeist','BeVietnamPro','NotoSans','NotoSerif'];
  await Promise.all(families.flatMap(f=>[400,500,600,700].map(w=>document.fonts.load(w+' 20px '+f,'HUẾ Ắ Ệ Ữ'))));
  await Promise.all(['BeVietnamPro','NotoSans','NotoSerif'].map(f=>document.fonts.load('italic 400 20px '+f,'Huế có chi hay?')));
  await document.fonts.ready;
  const corpus=await (await fetch('corpus.json')).json();const c=document.createElement('canvas'),ctx=c.getContext('2d');
  const metrics=families.map(f=>{ctx.font='400 32px '+f;return {family:f,check:document.fonts.check('400 20px '+f,'HUẾ Ắ Ệ Ữ'),runs:corpus.tone_rows_nfc.flat().map(s=>{const n=s.normalize('NFD'),a=ctx.measureText(s),b=ctx.measureText(n);return {nfc:s,nfd:n,widthNFC:a.width,widthNFD:b.width,ascent:a.actualBoundingBoxAscent,descent:a.actualBoundingBoxDescent};})};});
  const data={status:document.fonts.status,faces:[...document.fonts].map(f=>({family:f.family,status:f.status,weight:f.weight,style:f.style})),metrics,note:'font.check và cmap không chứng minh per-glyph rendered face; canvas metrics không thay quan sát ink trên ảnh.'};
  document.querySelector('#metrics').textContent=JSON.stringify(data,null,2);document.querySelector('#status').textContent='READY · '+document.fonts.status+' · NFC/NFD corpus sẵn sàng · 3 family ứng viên tải local, chưa áp dụng production.';
}
validate().catch(e=>document.querySelector('#status').textContent='FONT ERROR: '+e.message);
'''
(P/'preview.js').write_text(js,encoding='utf-8')
print('Independent HTML/CSS/JS preview created; production untouched')
